import {installDeckLanguage} from './deck-language.js?v=bilingual-1';
import {connectLiveDeck} from '../js/deck-live.js?v=keynote-1';
const reference=await fetch(new URL('./reference.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('Reference unavailable');return r.json();});
const languageCatalogue=await fetch(new URL('./translations-id.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('Translations unavailable');return r.json();});
const assets=new URL('../',import.meta.url).href;
const local=['localhost','127.0.0.1'].includes(location.hostname);
const app=window.SIGNAL_HOSTING?.frontendUrl||(local&&location.port==='8090'?'https://irfanradarma.github.io/grc50':location.origin);
const guideApp=['localhost','127.0.0.1'].includes(location.hostname)&&location.port==='8090'?location.origin+'/_app':app;
const presenter=new URLSearchParams(location.search).get('present')==='1';
document.body.classList.toggle('presenter',presenter);
document.querySelectorAll('[data-presenter-only]').forEach(element=>element.hidden=!presenter);
const params=new URLSearchParams(location.search),session=(params.get('session')||'').toUpperCase();
let joinHref=/^[A-Z0-9]{6}$/.test(session)?app+'/audience/?session='+session:app+'/audience/';
try{const supplied=new URL(params.get('join')||joinHref);if(['https:','http:'].includes(supplied.protocol)&&!supplied.username&&!supplied.password)joinHref=supplied.href;}catch{}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<img class="icon" src="${assets}icons/${name}.svg" alt="">`;
const pill=(label,tone='')=>`<span class="pill ${tone}">${label}</span>`;
const label=text=>`<p class="eyeline">${text}</p>`;
const arrow='<span class="arrow" aria-hidden="true">→</span>';
const chain=items=>`<div class="chain">${items.map(([name,detail,ic],i)=>`${i?arrow:''}<div class="chain-node">${ic?icon(ic):''}<strong>${name}</strong>${detail?`<span>${detail}</span>`:''}</div>`).join('')}</div>`;
const title=(text,sub='')=>`<div class="heading"><h1>${text}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div>`;
const mark=(text,cls='')=>`<span class="accent ${cls}">${text}</span>`;
const study=kind=>`<button class="source-link" data-details>${esc(reference.research[kind].publisher||reference.research[kind].authors)} · ${reference.research[kind].year} ↗</button>`;
const dots=(count,total=100)=>`<div class="dot-field" aria-label="${count}%" role="img">${Array.from({length:total},(_,i)=>`<i class="${i<count?'filled':''}" style="--i:${i}"></i>`).join('')}</div>`;
const metric=(number,name,extra='')=>`<div class="metric"><b>${number}</b><span>${name}</span>${extra?`<small>${extra}</small>`:''}</div>`;
const sources=()=>`<div class="source-orbit"><div class="orbit-hub">${icon('radar')}<b>One risk.</b></div>${[['News','radar'],['Reports','clipboard-check'],['Audit','shield-alert'],['CMCA','scan-line']].map(([name,ic],i)=>`<div class="orbit-source os-${i}">${icon(ic)}<b>${name}</b><span class="orbit-dot"></span></div>`).join('')}<svg viewBox="0 0 900 470" aria-hidden="true"><path d="M140 100Q450 100 450 235M760 100Q450 100 450 235M140 370Q450 370 450 235M760 370Q450 370 450 235"/></svg></div>`;
function matrix(){return `<div class="matrix-example"><div class="risk-map" aria-label="Worked assessment: likelihood 3 to 4, impact 4; score 12 to 16"><span class="axis-y">LIKELIHOOD</span>${[5,4,3,2,1].map(l=>[1,2,3,4,5].map(i=>`<div class="risk-cell r${l*i>15?'high':l*i>9?'mid':'low'}">${l===3&&i===4?'<span class="risk-dot before">12</span>':''}${l===4&&i===4?'<span class="risk-dot after">16</span>':''}</div>`).join('')).join('')}<span class="axis-x">IMPACT →</span></div><div class="score-story"><span>Same impact. Changed likelihood.</span><div><b>12</b><i>→</i><b class="hot">16</b></div><small>Illustrative tolerance ≤12</small></div></div>`;}
const guides={
 menus:['monitoring','Open the risk with an alert.',[['01','Open Risk Monitoring','Select Risk Monitoring from the workspace navigation.'],['02','Find the new alert','The highlighted count shows evidence waiting for your review.'],['03','Open the risk','Click the risk row or its alert. Review, score and respond in one connected flow.']]],
 capture:['signal-review','Review the evidence.',[['01','Read the source','Review the news summary and open the original article.'],['02','Challenge the relevance','Read why it could affect this risk and its objective.'],['03','Accept or decline','Decide for every signal before moving to the combined assessment.']]],
 assessment:['score-review','Confirm your assessment.',[['01','Compare P and S','P marks the previous score: 12. S proposes 16 after the accepted signal.'],['02','Choose your position','Keep the suggestion or select another matrix cell. Explain a custom or unchanged score.'],['03','Save risk score','The status beside the bottom-right button states which choice you made.']]],
 mitigation:['mitigation','Turn the alert into action.',[['01','Check the tolerance','The reassessed score of 16 exceeds the tolerance of 12.'],['02','Choose the response','Accept the suggested action or create your own.'],['03','Define the expected effect','Assign an owner and deadline; declare the expected likelihood and impact reductions.']]],
 residual:['residual','Make the expected protection explicit.',[['01','Review the reduction','A likelihood reduction of 1 changes L4 to L3; impact stays at 4.'],['02','Compare 16 with 12','Projected residual is 3 \u00d7 4 = 12, meeting tolerance if the plan succeeds.'],['03','Finish and update risk','Save signals, assessment and the new mitigation together. Verify delivery and effectiveness afterwards.']]],
 dashboard:['dashboard','See the decision reflected.',[['01','Check the dashboard','The map shows projected residual exposure, including the declared mitigation effect.'],['02','Track commitments','The new plan appears in Mitigation plans with its owner, deadline and expected effect.'],['03','Understand the projection','Residual 12 assumes effective mitigation. The assessed score of 16 remains in Decision history.']]]
};
const guideSizes={monitoring:[1440,1000],'signal-review':[1089,393],'score-review':[1089,766],mitigation:[1089,714],residual:[1089,639],dashboard:[1425,990]};
const guideMarks={
 menus:[[1,1,17,15,5],[2,84,40,10,7],[3,20,40,34,7]],
 capture:[[1,0.5,0.5,98,38],[2,2,39,96,31],[3,74,81,24,16]],
 assessment:[[1,76,40,14,16],[2,61,32,34,37],[3,85,90,14,7]],
 mitigation:[[1,0.5,5,99,16],[2,65,45,34,7],[3,1,85,98,14]],
 residual:[[1,1,0.5,98,13],[2,2,39,96,24],[3,82,86,17,8]],
 dashboard:[[1,61,45,35,47],[2,78,28,18,12],[3,61,83,35,8]]
};
function annotatedGuide(key,file,alt){const [w,h]=guideSizes[file];return `<svg class="guide-annotated" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(alt)} Numbered highlights match the instructions."><image href="${assets}images/walkthrough/${file}.png" width="${w}" height="${h}"/>${guideMarks[key].map(([n,x,y,rw,rh])=>{const px=x*w/100,py=y*h/100,size=Math.max(w,h)*.017;return `<g class="guide-mark gm-${n}"><rect x="${px}" y="${py}" width="${rw*w/100}" height="${rh*h/100}" rx="${size/3}"/><circle cx="${px+size}" cy="${py+size}" r="${size}"/><text x="${px+size}" y="${py+size}" font-size="${size}">${n}</text></g>`;}).join('')}</svg>`;}
function demo(key,headline,caption){const [file,alt,steps]=guides[key];return {kind:'still-guide',title:headline,html:`${title(headline)}<div class="guide-story"><figure class="guide-screenshot">${annotatedGuide(key,file,alt)}</figure><ol class="guide-instructions">${steps.map(([n,h,d],i)=>`<li class="gi-${i+1}"><span>${n}</span><div><strong>${h}</strong><p>${d}</p></div></li>`).join('')}</ol></div><p class="micro">${caption}<span>Match each number to the highlighted area.</span></p>`};}
const overviewMenus=[['dashboard','Dashboard','See the objective, risk map and action commitments.'],['monitoring','Risk Monitoring','Review risks, scores and owners. The second tab lists mitigation plans and deadlines.'],['trigger','Risk Trigger','Choose news publishers and inspect report, audit and Continuous Assurance sources.']];

function divider(n,headline,sub){const names=reference.chapters.map(c=>c.title.toUpperCase());return {tone:"night",kind:"divider",title:headline,html:`<div class="section-number" aria-hidden="true">0${n}</div><div class="section-kicker"><span>SECTION 0${n} / 04</span><strong>${names[n-1]}</strong></div>${title(headline,sub)}<div class="chapter-dots">${[1,2,3,4].map(i=>`<i class="${i===n?"on":""}"></i>`).join('')}</div>`};}
const cycleSteps=[
 ['Identify','Discover emerging exposure.','AI reads context and evidence to draft candidate risks.','People validate relevance, completeness and accountability.','radar'],
 ['Assess','Challenge the assumptions.','AI brings evidence together and proposes an assessment.','People evaluate uncertainty, set the score and own the judgment.','scan-line'],
 ['Treat','Shape a proportionate response.','AI drafts options, trade-offs and mitigation plans.','People authorize the action, resources, owner and deadline.','route'],
 ['Monitor','Keep watching what changes.','AI tracks signals, indicators and action evidence.','People confirm exceptions, reassess and verify effectiveness.','circle-check']
];
const riskCycle=`${title(`AI can assist ${mark('the whole cycle.')}`)}<div class="cycle-canvas cycle-all"><div class="risk-cycle"><svg viewBox="0 0 1000 420" preserveAspectRatio="none" aria-hidden="true"><path d="M245 75H755Q920 75 920 210T755 345H245Q80 345 80 210T245 75"/></svg>${cycleSteps.map(([name,tagline,,,ic],i)=>`<div class="cycle-step cycle-${i}">${icon(ic)}<span>0${i+1}</span><b>${name}</b><small>${tagline}</small></div>`).join('')}<div class="cycle-human">${icon('user-round-check')}<strong>Human<br>authority.</strong><small>Validate &#183; approve &#183; own</small></div></div>${cycleSteps.map(([name,,ai,human],i)=>`<aside class="cycle-note cycle-note-${i}"><small>0${i+1} / ${name.toUpperCase()}</small><b>${ai}</b><p>${human}</p></aside>`).join('')}</div>`;
const phases=[
 ['S','Sense','Listen beyond the register.','News, reports, audit findings and automated exceptions. Use permitted sources and retain provenance.','radar'],
 ['I','Interpret','Context before noise.','Relate each signal to the organization, its objectives and registered risks. A topic match alone does not establish exposure.','target'],
 ['G','Gauge','Explain what could change.','Show the challenged assumption, evidence quality and uncertainty. Suggest a review; do not manufacture precision.','scan-line'],
 ['N','Notify','The right owner. In time.','Bring a concise decision brief to the person who owns the risk. Human review can approve or decline the relationship.','user-round-check'],
 ['A','Act','Judgment becomes action.','The owner keeps or updates the assessment, then approves or customizes a mitigation when warranted.','route'],
 ['L','Learn','Close the loop.','Verify implementation and effectiveness. Feed approved changes and new evidence into the next review.','circle-check']
];
const framework=`${title('Signal Framework')}<div class="signal-atlas"><div class="signal-acronym" aria-label="SIGNAL">${phases.map(([letter],i)=>`<b class="signal-color-${i}">${letter}</b>`).join('')}</div><div class="signal-role-groups"><div>${icon('bot')}<b>AI agent</b><span>Prepare evidence and advice</span></div><div>${icon('user-round-check')}<b>Human</b><span>Decide, act and verify</span></div></div><div class="signal-columns">${phases.map(([letter,name,tagline,copy],i)=>`<article class="signal-color-${i}" aria-label="${letter}: ${name}"><h2>${name}</h2><h3>${tagline}</h3><p>${copy}</p></article>`).join('')}</div></div><p class="micro">A continuous path from evidence to action.<span>Human judgment can challenge the evidence at every phase.</span></p>`;
const companies=[['Nusa Logistik','Export logistics','45%','Revenue tied to US-bound exporters','route'],['Pangan Ritel','Seafood exports','60%','Export sales to US buyers','database'],['Cakrawala Digital','Domestic software','0','Goods-export contracts in this case','network']];
const orgs=(reveal=false)=>`<div class="organizations">${companies.map(([name,field,value,detail,ic],i)=>`<article class="org ${reveal?'exposure':''}" data-exposure="${i}">${icon(ic)}<small>${field}</small><h2>${name}</h2><b class="org-number">${value}</b><p>${detail}</p>${reveal?`<div class="exposure-answer"><span>${i<2?'● Strong relevance':'● No direct link established'}</span><p>${['Customer demand supports the growth and hub investment case.','Product coverage, buyer pricing and margin need review.','No direct goods-tariff dependency in the supplied context.'][i]}</p></div>`:''}</article>`).join('')}</div>`;
