 'our-pain-point':{tone:'night',kind:'disconnect-explained',title:'Disconnected decisions. Unprotected objectives.',html:`${title('Disconnected decisions.<br><span class="silver">Unprotected objectives.</span>')}<div class="disconnect-systems">${[['Goal / KPI','Tracked','target'],['Risk assessment','Filed','shield-alert'],['Audit finding','Reported','clipboard-check']].map(([name,state,ic])=>`<div>${icon(ic)}<b>${name}</b><small>${state}</small></div>`).join('<span class="disconnect-break" aria-hidden="true">&#8602;</span>')}</div><div class="disconnect-questions"><article><small>RISK &#8594; GOAL</small><h2>Where is the early warning?</h2><p>When exposure rises, does the risk assessment warn that the target may be missed?</p></article><article><small>ASSURANCE &#8594; RISK</small><h2>What changed after the finding?</h2><p>When an audit exposes a serious weakness, does the risk score or response change?</p></article></div><p class="anchor">A report is only useful when the evidence reaches the next decision.</p>`},
 'evidence-risk-management':{title:'The strategic advantage gap.',kind:'stat',html:`<div class="stat-copy">${label('RISK MANAGEMENT / STRATEGIC VALUE')}<h1><span class="mega">89<span>%</span></span><span class="stat-head">did not report a unique<br>strategic advantage.</span></h1><p>Only 11% reported one.</p>${study('risk')}<small class="scope">Rounded complement · self-reported perceptions<br>331 executive / board respondents · Q2 2026</small></div>${dots(89)}`},
 'evidence-assurance':{tone:'night',title:'The assurance alignment gap.',kind:'stat',html:`<div class="stat-copy">${label('ASSURANCE / ALIGNMENT')}<h1><span class="mega">49<span>%</span></span><span class="stat-head">of business executives<br>saw an alignment gap.</span></h1><p>Internal audit and the other lines.</p>${study('audit')}<small class="scope">Business-executive subgroup · perceived alignment<br>Not an audit failure rate</small></div>${dots(49)}`},
 'evidence-how-the-gap-happens':{kind:"report-gap",title:"A report is not a decision.",html:`${label("WHY THE GAP PERSISTS")}${title('A report is<br>not <span class="accent">a decision.</span>')}<div class="gap-sequence"><div><b>Risk report</b><small>Prepared and filed</small></div><i aria-hidden="true">&#8603;</i><div><b>Management decision</b><small>Assumptions unchanged</small></div><i aria-hidden="true">&#8603;</i><div><b>Objective</b><small>Exposure unresolved</small></div></div><p class="anchor">Reporting adds value when it changes a decision.</p>${study("paper")}<small class="scope">Agarwal &amp; Kallapur: disconnected reporting in financial institutions.<br>Qualitative field evidence; not a prevalence estimate.</small>`},
