 'a-busier-information-environment':{tone:'night',title:'Keep exploring. The story continues.',html:`${title('Keep exploring.<br><span class="silver">The story continues.</span>')}<div class="value-words"><span>Dynamic.</span><span>Responsive.</span><span>Connected.</span><span>Accountable.</span></div><p class="anchor">More signals in your inbox.<br>Next: how AI also supports assurance work.</p><p class="micro">Presenter releases the next batches in Admin <span>No waiting period. Continue as risk manager.</span></p>`},
 'section-action':divider(4,'From connected decisions.<br>To integrated control.','Kemenkeu: the SPIT initiative and SIPT.'),
